export function useAdminText() {
  try {
    const { lang } = useI18n();
    return (s: string) =>
      lang === "en" ? s : (words[s]?.[lang === "rw" ? 0 : lang === "fr" ? 1 : 2] ?? s);
  } catch {
    return (s: string) => s;
  }
}
